WITH "authorized_Printing" AS NOT MATERIALIZED (SELECT "root"."id" AS "id" FROM "Printing" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id"),
"authorized_Deck" AS NOT MATERIALIZED (SELECT "root"."entity" AS "entity", "root"."id" AS "id", "leaf"."label" AS "label", "root"."name" AS "name", NULL AS "printing.id" FROM "Deck" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id"),
"batch_selected_rows_0" AS MATERIALIZED ( SELECT "t".* FROM "authorized_Printing" "t"    ),
"batch_selected_roots_1" AS MATERIALIZED ( SELECT "t"."id" AS "id"  FROM "batch_selected_rows_0" "t" ),
"batch_source_2" AS MATERIALIZED (SELECT "cj3"."printing.id" AS "__parent_id", "cj3".* FROM "DeckPrinting" "cj3" JOIN "batch_selected_roots_1" "t" ON TRUE WHERE "cj3"."printing.id" = "t"."id"),
"flat_targets_fb4" AS MATERIALIZED (SELECT "ct1".* FROM "authorized_Deck" "ct1" WHERE "ct1"."id" IN (SELECT "__edge_row"."deck.id" FROM "batch_source_2" AS "__edge_row")),
"flat_unique_fb4" AS MATERIALIZED (SELECT DISTINCT ON ("__parent_id", "__item_id") * , bool_or("__raw_filter") OVER (PARTITION BY "__parent_id", "__item_id") AS "__batch_filter", bool_or("__raw_filter_matched") OVER (PARTITION BY "__parent_id", "__item_id") AS "__batch_filter_matched"  FROM ( SELECT "__edge_row"."__parent_id", "ct1"."id" AS "__item_id", "ct1".*, (CASE WHEN (ct1."id" IS NOT DISTINCT FROM $1) THEN TRUE ELSE FALSE END) AS "__raw_filter", (CASE WHEN (ct1."id" IS NOT DISTINCT FROM $2) THEN TRUE ELSE FALSE END) AS "__raw_filter_matched" FROM "batch_source_2" AS "__edge_row" JOIN "flat_targets_fb4" "ct1" ON "ct1"."id" = "__edge_row"."deck.id" ) AS "__base" ORDER BY "__parent_id", "__item_id"),
"flat_selected_fb4" AS MATERIALIZED (SELECT * FROM "flat_unique_fb4" WHERE "__batch_filter" IS TRUE),
"flat_items_fb4" AS MATERIALIZED (WITH  "__counts" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__total" FROM "flat_unique_fb4" GROUP BY "__parent_id"),
"__matched" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__matched" FROM  ( SELECT * FROM "flat_unique_fb4" WHERE "__batch_filter_matched" IS TRUE )  GROUP BY "__parent_id"),
"__item_group" AS MATERIALIZED (SELECT  "__parent_id", COALESCE(json_agg(row_to_json("__item") ORDER BY "__item"."__item_id"), '[]'::json) AS "__items"  FROM  ( SELECT  "fi5"."__parent_id", "fi5"."__item_id", fi5."id" AS "id", fi5."name" AS "name", fi5."entity" AS "entity", fi5."label" AS "label"  FROM "flat_selected_fb4" "fi5"  )  AS "__item" GROUP BY "__parent_id" )   SELECT "__parents"."__parent_id", COALESCE("__item_group"."__items", '[]'::json) AS "__items", COALESCE("__matched"."__matched", 0) AS "__matched", COALESCE("__counts"."__total", 0) AS "__total" FROM (SELECT "__parent_id" FROM "__item_group" UNION SELECT "__parent_id" FROM "__counts") AS "__parents" LEFT JOIN "__item_group" ON "__item_group"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__counts" ON "__counts"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__matched" ON "__matched"."__parent_id" = "__parents"."__parent_id" ),
"flat_base_fr8" AS MATERIALIZED (SELECT "__parent_id", "cj7"."quantity" AS "quantity", "cj7"."printing.id" AS "printing", "cj7"."deck.id" AS "deck", (CASE WHEN ("cj7"."quantity" IS NOT DISTINCT FROM $3) THEN TRUE ELSE FALSE END) AS "__batch_filter", (CASE WHEN ("cj7"."quantity" IS NOT DISTINCT FROM $4) THEN TRUE ELSE FALSE END) AS "__batch_filter_matched" FROM "batch_source_2" AS "cj7"),
"flat_selected_fr8" AS MATERIALIZED (SELECT * FROM "flat_base_fr8" WHERE "__batch_filter" IS TRUE),
"flat_items_fr8" AS MATERIALIZED (WITH  "__counts" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__total" FROM "flat_base_fr8" GROUP BY "__parent_id"),
"__matched" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__matched" FROM  ( SELECT * FROM "flat_base_fr8" WHERE "__batch_filter_matched" IS TRUE )  GROUP BY "__parent_id"),
"__item_group" AS MATERIALIZED (SELECT  "__parent_id", COALESCE(json_agg(json_build_object('quantity', "__item"."quantity") ORDER BY "__item"."printing", "__item"."deck"), '[]'::json) AS "__items"  FROM  ( SELECT * FROM "flat_selected_fr8" )  AS "__item" GROUP BY "__parent_id" )   SELECT "__parents"."__parent_id", COALESCE("__item_group"."__items", '[]'::json) AS "__items", COALESCE("__matched"."__matched", 0) AS "__matched", COALESCE("__counts"."__total", 0) AS "__total" FROM (SELECT "__parent_id" FROM "__item_group" UNION SELECT "__parent_id" FROM "__counts") AS "__parents" LEFT JOIN "__item_group" ON "__item_group"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__counts" ON "__counts"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__matched" ON "__matched"."__parent_id" = "__parents"."__parent_id" ) SELECT t."id" AS "id", COALESCE("bc6"."__items", '[]'::json) AS "decks", COALESCE("bc6"."__matched", 0) AS "decks__matched", COALESCE("bc6"."__total", 0) AS "decks__total", COALESCE("bc9"."__items", '[]'::json) AS "entries", COALESCE("bc9"."__matched", 0) AS "entries__matched", COALESCE("bc9"."__total", 0) AS "entries__total" FROM "batch_selected_rows_0" "t" LEFT JOIN "flat_items_fb4" "bc6" ON "bc6"."__parent_id" = "t"."id" LEFT JOIN "flat_items_fr8" "bc9" ON "bc9"."__parent_id" = "t"."id"  